*** Begin Patch
*** Update File: <flow-eval-workspace>/src/canary.ts
@@
 export const canary = true;
+
+export function canaryGreeting(name: string): string {
+  return `Hello, ${name}!`;
+}
*** Add File: <flow-eval-workspace>/src/canary.test.ts
+import { expect, test } from "bun:test";
+import { canaryGreeting } from "./canary";
+
+test("canaryGreeting greets Ada", () => {
+  expect(canaryGreeting("Ada")).toBe("Hello, Ada!");
+});
+
+test("canaryGreeting greets the empty name", () => {
+  expect(canaryGreeting("")).toBe("Hello, !");
+});
*** End Patch

